item.command:
/bin/bash -lc "python3 - <<'PY'
import urllib.request, hashlib, json
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
paths=['examples/benchmark.py','examples/5dfr_solv-cube_equil.pdb','wrappers/python/openmm/app/data/amber99sb.xml','wrappers/python/openmm/app/data/tip3p.xml']
for path in paths:
 try:
  blob=urllib.request.urlopen(base+path,timeout=30).read()
  print(json.dumps({'url':base+path,'bytes':len(blob),'sha256':hashlib.sha256(blob).hexdigest()}))
  if path.endswith('benchmark.py'):
   lines=blob.decode().splitlines()
   for n,line in enumerate(lines):
    if any(s in line for s in ['test == \\'pme\\'','5dfr','LangevinMiddle','hydrogenMass','constraint','default=','default =','amber99sb','tip3p','setConstraintTolerance']):
     print(str(n+1)+': '+line)
 except Exception as e: print(json.dumps({'url':base+path,'error':str(e)}))
for url in ['https://api.github.com/repos/openmm/openmm/git/ref/tags/8.2.0','https://pypi.org/pypi/openmm/8.2.0/json']:
 try:
  obj=json.load(urllib.request.urlopen(url,timeout=30))
  print(json.dumps({'url':url,'object':obj.get('object'),'requires_python':obj.get('info',{}).get('requires_python'),'linux_wheels':[{'filename':v['filename'],'bytes':v['size'],'sha256':v['digests']['sha256']} for v in obj.get('urls',[]) if 'manylinux' in v['filename']]}))
 except Exception as e: print(str(e))
PY"

